namespace {
using nnn::Byte;using nnn::Word;using nnn::Value;using nnn::ErrorCode;using nnn::ScriptControlProfile;
constexpr Word volume=0x33330069U,print=0x22220001U,end=0x55560005U;
void require(bool b,const std::string& s){if(!b)throw std::runtime_error(s);}
void status(const nnn::Status& s,ErrorCode code){require(s.code==code,std::string(nnn::error_name(s.code))+": "+s.detail);}
nnn::SkipFlags flags(Word m){return{(m&1U)!=0,(m&2U)!=0,(m&4U)!=0,(m&8U)!=0,(m&16U)!=0};}
bool equal(const nnn::VoiceChannelState& a,const nnn::VoiceChannelState& b){return a.work==b.work&&a.fade_count_ms==b.fade_count_ms&&a.fade_time_ms==b.fade_time_ms&&a.fade_from_volume==b.fade_from_volume&&a.fade_target_volume==b.fade_target_volume&&a.object_present==b.object_present&&a.buffer_present==b.buffer_present&&a.data_present==b.data_present;}
bool equal(const nnn::VoiceState& a,const nnn::VoiceState& b){if(a.next_fade_units!=b.next_fade_units)return false;for(std::size_t i=0;i<4;++i)if(!equal(a.channels[i],b.channels[i]))return false;return true;}
nnn::VoiceState seed(Value fade=0){nnn::VoiceState s;s.next_fade_units=fade;for(std::size_t i=0;i<4;++i){auto& c=s.channels[i];c.work[0]=1;c.work[2]=static_cast<Value>(10U+i);c.work[15]=1;c.fade_count_ms=static_cast<Value>(7U+i);c.fade_from_volume=static_cast<Value>(30U+i);c.fade_target_volume=static_cast<Value>(20U+40U*(i%2U));c.buffer_present=c.data_present=true;}return s;}
std::vector<Byte> fixture(const std::string& name){const auto p=std::filesystem::path(NNN_VOICE_CHANNEL_FIXTURE_DIR)/name;std::ifstream input(p,std::ios::binary);require(static_cast<bool>(input),"fixture absent");return{std::istreambuf_iterator<char>(input),std::istreambuf_iterator<char>()};}
std::vector<Word> decoded(const std::string& name){const auto b=fixture(name);require(b.size()%4U==0,"unaligned fixture");std::vector<Word> out;for(std::size_t i=0;i<b.size();i+=4U)out.push_back((static_cast<Word>(b[i])|(static_cast<Word>(b[i+1])<<8U)|(static_cast<Word>(b[i+2])<<16U)|(static_cast<Word>(b[i+3])<<24U))^UINT32_MAX);return out;}
std::vector<Byte> encoded(const std::vector<Word>& words){std::vector<Byte> b;for(Word w:words){w^=UINT32_MAX;for(unsigned shift=0;shift<32;shift+=8)b.push_back(static_cast<Byte>(w>>shift));}return b;}
std::string json_array(const std::vector<std::string>& rows){std::string s="[";for(std::size_t i=0;i<rows.size();++i){if(i)s+=',';s+=rows[i];}return s+"]";}
struct Host:nnn::CScriptCallBack {
    nnn::CExecScript* vm=nullptr;nnn::VoiceVolumeController voice;nnn::VoiceOutputs output;
    std::array<std::string,2> names{{"AA_current","BB_current"}};Value base=49;
    bool apply=true,accept=true;std::function<void(Word)> during;
    std::vector<std::string> events,live;std::vector<Word> pcs,channels;std::vector<std::pair<Word,Value>> physical;
    std::vector<std::vector<Value>> retained;std::size_t reads=0;nnn::Status applied;
    std::vector<std::tuple<Word,Word,Word>> skipped;
    void UnhandledInstruction(Word pc,Word identify,Word opcode)override{skipped.emplace_back(pc,identify,opcode);}
    Host(){output.set_volume=[this](Word ch,Value value){physical.emplace_back(ch,value);};output.stop=[](Word){throw std::runtime_error("unexpected immediate Stop");};}
    nnn::VoiceLiveInputs inputs(Word ch){return{[this]{return GetSkipFlags();},[this]{live.push_back("base");return base;},[this,ch]{live.push_back("name"+std::to_string(ch));return names.at(ch);},[this,ch](const std::string& name){live.push_back("role"+std::to_string(ch));require(name==names.at(ch),"closure bound wrong voice name");nnn::VoiceCharacterProfile p;p.names={"skip","description","AA","A","BB","B"};p.slider_delta=100;p.packed_sliders[0]=(10U<<5U)|(15U<<10U);return nnn::resolve_voice_adjustment(name,p);}};}
    bool ReceiveNumericScriptCommand(Word code,Value count,const std::vector<Value>& p,Value p3)override{require(code==volume&&count==2&&p.size()==2&&p[0]>=0&&p[0]<=1&&p[1]==-999&&p3==0,"wrong volume wire");const auto ch=static_cast<Word>(p[0]);pcs.push_back(vm->GetPC());channels.push_back(ch);retained.push_back(p);require(vm->GetCallDepth()==0,"unexpected frame");events.push_back("{\"kind\":\"numeric_script\",\"code\":858980457,\"para1\":2,\"parameters\":["+std::to_string(ch)+",-999],\"para3\":0}");if(during)during(ch);if(!accept)return false;if(!apply)return true;applied=voice.ApplyMinus999(ch,inputs(ch),output);return static_cast<bool>(applied);}
    void ReceiveScriptCommand(Word code,Value p1,const std::string& text,Value p3)override{require(code==print&&p1==0&&text=="M"&&p3==0,"unexpected text event");pcs.push_back(vm->GetPC());events.push_back("{\"kind\":\"script\",\"code\":572653569,\"para1\":0,\"text_hex\":\"4d\",\"para3\":0}");}
    void PreReceiveScriptData(Word,Value,const std::string&)override{throw std::runtime_error("predata");}
    void ReceiveUserCommand0(Word,const std::vector<Value>&)override{throw std::runtime_error("user command");}
    void ReceiveUserFunction0(Word,const std::vector<Value>&)override{throw std::runtime_error("user function");}
    Value GetVarData(Word)override{++reads;throw std::runtime_error("evaluated VAR");}
    Value GetCalcuVarData(Word)override{++reads;throw std::runtime_error("evaluated expression");}
    void SetVarData(Word,Value)override{throw std::runtime_error("variable write");}
};
void load(nnn::CExecScript& vm,const std::vector<Word>& w,ScriptControlProfile p=ScriptControlProfile::Closed){status(vm.LoadBytes(encoded(w),"channel",{},nullptr,p),ErrorCode::Ok);}
void reject(const std::vector<Word>& w,ErrorCode error,ScriptControlProfile p){Host h;nnn::CExecScript vm(h);h.vm=&vm;status(vm.LoadBytes(encoded(w),"bad",{},nullptr,p),error);require(!vm.IsLoaded()&&h.events.empty(),"bad input installed/dispatched");}
struct Suite{int passed=0,failed=0;void test(const std::string& name,const std::function<void()>& body){try{body();++passed;std::cout<<"PASS "<<name<<'\n';}catch(const std::exception& e){++failed;std::cerr<<"FAIL "<<name<<": "<<e.what()<<'\n';}}};
}

int main(){Suite suite;
    suite.test("legacy controller entry equals explicit channel zero",[]{Host a,b;const auto initial=seed(2);status(a.voice.SetState(initial),ErrorCode::Ok);status(b.voice.SetState(initial),ErrorCode::Ok);status(a.voice.ApplyMinus999(a.inputs(0),a.output),ErrorCode::Ok);status(b.voice.ApplyMinus999(0,b.inputs(0),b.output),ErrorCode::Ok);require(equal(a.voice.State(),b.voice.State())&&a.physical==b.physical,"old entry not channel0 wrapper");});
    for(Word ch=0;ch<2;++ch)suite.test("selected channel isolation and bound role "+std::to_string(ch),[ch]{Host h;const auto initial=seed();status(h.voice.SetState(initial),ErrorCode::Ok);status(h.voice.ApplyMinus999(ch,h.inputs(ch),h.output),ErrorCode::Ok);auto expected=initial;auto& c=expected.channels[ch];c.fade_count_ms=c.fade_time_ms=0;c.fade_target_volume=ch==0?50:100;c.work[2]=-999;require(equal(h.voice.State(),expected)&&h.physical==std::vector<std::pair<Word,Value>>{{ch,ch==0?50:100}}&&h.live==std::vector<std::string>{"base","name"+std::to_string(ch),"role"+std::to_string(ch)},"channel state/getter/output crossed");});
    suite.test("all32 global skip masks and independent work15 permissions",[]{for(Word m=0;m<32;++m)for(Word ch=0;ch<2;++ch)for(const Value permission:{0,-7}){Host h;auto initial=seed(2);initial.channels[ch].work[15]=permission;initial.channels[1U-ch].work[15]=permission==0?1:0;status(h.voice.SetState(initial),ErrorCode::Ok);h.SetSkipFlags(flags(m));status(h.voice.ApplyMinus999(ch,h.inputs(ch),h.output),ErrorCode::Ok);auto expected=initial;expected.next_fade_units=0;const bool allowed=(m&4U)==0&&permission!=0;if(allowed){auto& c=expected.channels[ch];c.fade_count_ms=0;c.fade_time_ms=200;c.fade_from_volume=c.fade_target_volume;c.fade_target_volume=ch==0?50:100;c.work[2]=-999;}require(equal(h.voice.State(),expected)&&h.physical.empty()&&h.live.size()==(allowed?3U:0U),"skip/work15 shared incorrectly");}});
    suite.test("channel one getter remains live after previous channel zero call",[]{Host h;status(h.voice.SetState(seed()),ErrorCode::Ok);status(h.voice.ApplyMinus999(0,h.inputs(0),h.output),ErrorCode::Ok);status(h.voice.ApplyMinus999(1,h.inputs(1),h.output),ErrorCode::Ok);h.names[1]="AA_new";status(h.voice.ApplyMinus999(1,h.inputs(1),h.output),ErrorCode::Ok);require(h.physical==std::vector<std::pair<Word,Value>>{{0,50},{1,100},{1,50}}&&h.voice.State().channels[0].fade_target_volume==50,"cached/wrong name or global role binding");});
    for(const Word ch:{2U,3U,UINT32_MAX})suite.test("unsupported controller channel before live or writes "+std::to_string(ch),[ch]{Host h;const auto initial=seed(9);status(h.voice.SetState(initial),ErrorCode::Ok);nnn::VoiceLiveInputs live;live.skip_flags=[]{throw std::runtime_error("unsupported called live");return flags(0);};status(h.voice.ApplyMinus999(ch,live,h.output),ErrorCode::UnsupportedInstruction);require(equal(h.voice.State(),initial)&&h.physical.empty(),"unsupported channel cleared global fade");});
    suite.test("Busy precedes unsupported channel and invalid getter",[]{Host h;status(h.voice.SetState(seed()),ErrorCode::Ok);h.output.set_volume=[&](Word ch,Value){require(ch==1,"wrong output channel");status(h.voice.ApplyMinus999(2,{}),ErrorCode::Busy);status(h.voice.ApplyMinus999(0,{}),ErrorCode::Busy);status(h.voice.Tick(0),ErrorCode::Busy);status(h.voice.SetWork(0,15,0),ErrorCode::Busy);};status(h.voice.ApplyMinus999(1,h.inputs(1),h.output),ErrorCode::Ok);status(h.voice.SetNextFade(1),ErrorCode::Ok);});
    for(const bool reverse:{false,true})suite.test(std::string("global nextfade consumed once in consecutive VM commands ")+(reverse?"one zero":"zero one"),[reverse]{auto w=decoded("voice01_labels.spt");if(reverse){w[36]=1;w[42]=0;}Host h;nnn::CExecScript vm(h);h.vm=&vm;const auto initial=seed(2);status(h.voice.SetState(initial),ErrorCode::Ok);load(vm,w);const auto r=vm.Exec();status(r.status,ErrorCode::Ok);require(r.return_code==print&&r.pc==50&&h.pcs==std::vector<Word>{32,38,44},"consecutive events did not continue");const Word first=reverse?1U:0U,second=1U-first;auto expected=initial;expected.next_fade_units=0;for(const Word ch:{first,second}){auto& c=expected.channels[ch];c.fade_count_ms=0;c.fade_time_ms=ch==first?200:0;if(ch==first)c.fade_from_volume=c.fade_target_volume;c.fade_target_volume=ch==0?50:100;c.work[2]=-999;}require(equal(h.voice.State(),expected)&&h.physical==std::vector<std::pair<Word,Value>>{{second,second==0?50:100}},"nextfade copied per channel/second consumed old fade");});
    suite.test("suppressed first command also consumes shared nextfade",[]{auto w=decoded("voice01_labels.spt");Host h;nnn::CExecScript vm(h);h.vm=&vm;auto initial=seed(3);initial.channels[0].work[15]=0;status(h.voice.SetState(initial),ErrorCode::Ok);load(vm,w);status(vm.Exec().status,ErrorCode::Ok);require(equal(h.voice.State().channels[0],initial.channels[0])&&h.voice.State().channels[1].fade_time_ms==0&&h.physical==std::vector<std::pair<Word,Value>>{{1,100}}&&h.voice.State().next_fade_units==0,"suppressed first retained shared fade");});
    suite.test("channel one scheduled fade and Tick preserve channel zero",[]{Host h;h.base=80;auto initial=seed(1);status(h.voice.SetState(initial),ErrorCode::Ok);auto live=h.inputs(1);live.character_adjust=[](const std::string&){return nnn::VoiceAdjustmentResult{{},0};};status(h.voice.ApplyMinus999(1,live,h.output),ErrorCode::Ok);require(h.physical.empty()&&h.voice.State().channels[1].fade_from_volume==60,"fade starts from wrong target");std::vector<std::pair<Word,Value>> volumes;std::vector<Word> stops;nnn::VoiceOutputs out{[&](Word ch,Value v){volumes.emplace_back(ch,v);},[&](Word ch){stops.push_back(ch);}};status(h.voice.Tick(50,out),ErrorCode::Ok);status(h.voice.Tick(100,out),ErrorCode::Ok);require(volumes==std::vector<std::pair<Word,Value>>{{1,30},{1,0}}&&stops==std::vector<Word>{1}&&h.voice.State().channels[1].fade_count_ms==150&&h.voice.State().channels[1].work[0]==0&&h.voice.State().channels[1].work[15]==0&&equal(h.voice.State().channels[0],initial.channels[0]),"Tick numbering/stop/overshoot changed");});
    suite.test("channel one absent object and output reject before writes",[]{for(int kind=0;kind<2;++kind){Host h;auto initial=seed();if(kind==0)initial.channels[1].object_present=false;status(h.voice.SetState(initial),ErrorCode::Ok);status(h.voice.ApplyMinus999(1,h.inputs(1)),ErrorCode::HostRejected);require(equal(h.voice.State(),initial),"missing selected channel output mutated");}});
    suite.test("channel one buffer absence needs no physical adapter",[]{Host h;auto initial=seed();initial.channels[1].buffer_present=false;initial.channels[0].object_present=false;status(h.voice.SetState(initial),ErrorCode::Ok);status(h.voice.ApplyMinus999(1,h.inputs(1)),ErrorCode::Ok);require(h.voice.State().channels[1].work[2]==-999&&equal(h.voice.State().channels[0],initial.channels[0]),"unselected object required/output wrongly required");});
    suite.test("channel one immediate exception keeps source partial state only there",[]{Host h;const auto initial=seed();status(h.voice.SetState(initial),ErrorCode::Ok);h.output.set_volume=[](Word ch,Value){require(ch==1,"wrong throwing channel");throw std::runtime_error("physical");};bool thrown=false;try{h.voice.ApplyMinus999(1,h.inputs(1),h.output);}catch(const std::runtime_error&){thrown=true;}auto expected=initial;expected.channels[1].fade_count_ms=expected.channels[1].fade_time_ms=0;require(thrown&&equal(h.voice.State(),expected),"throw changed other channel or committed target/work2");status(h.voice.SetNextFade(2),ErrorCode::Ok);});
    suite.test("channel one numeric false and throw preserve current PC",[]{for(int kind=0;kind<2;++kind){Host h;nnn::CExecScript vm(h);h.vm=&vm;status(h.voice.SetState(seed()),ErrorCode::Ok);load(vm,decoded("voice1_labels.spt"));if(kind==0)h.accept=false;else h.during=[](Word){throw std::runtime_error("numeric");};const auto before=h.voice.State();const auto r=vm.Exec();status(r.status,kind==0?ErrorCode::Ok:ErrorCode::CallbackFailed);require(r.pc==(kind==0?44U:32U)&&h.events.size()==(kind==0?2U:1U)&&equal(h.voice.State(),before),"decline or exception state");if(kind==0)require(h.skipped==std::vector<std::tuple<Word,Word,Word>>{{32,0x66660007U,volume}},"decline fallback");}});
    suite.test("channel one physical throw maps VM CallbackFailed and can retry",[]{Host h;nnn::CExecScript vm(h);h.vm=&vm;const auto initial=seed();status(h.voice.SetState(initial),ErrorCode::Ok);h.output.set_volume=[](Word,Value){throw 7;};load(vm,decoded("voice1_labels.spt"));status(vm.Exec().status,ErrorCode::CallbackFailed);require(vm.GetPC()==32&&h.voice.State().channels[1].work[2]==11&&equal(h.voice.State().channels[0],initial.channels[0]),"VM throw state");h.output.set_volume=[&](Word ch,Value v){h.physical.emplace_back(ch,v);};status(vm.Exec().status,ErrorCode::Ok);require(vm.GetPC()==44&&h.physical==std::vector<std::pair<Word,Value>>{{1,100}},"retry did not dispatch selected channel");});
    suite.test("channel one prepaid numeric budget at every boundary",[]{for(std::uint64_t budget=0;budget<=10;++budget){auto w=decoded("voice1_labels.spt");w[38]=3;w[39]=0x66660002U;w[40]=end;w[41]=3;w[42]=0x66660002U;w[43]=end;Host h;nnn::CExecScript vm(h);h.vm=&vm;const auto initial=seed();status(h.voice.SetState(initial),ErrorCode::Ok);load(vm,w);const auto r=vm.Exec(budget);status(r.status,budget<10?ErrorCode::BudgetExhausted:ErrorCode::Ok);require(r.work_used==(budget==0?0U:budget<7?1U:budget<10?7U:10U)&&h.channels.size()==(budget<7?0U:1U)&&h.physical.size()==(budget<7?0U:1U)&&vm.GetPC()==(budget==0?0U:budget<7?32U:38U)&&equal(h.voice.State().channels[0],initial.channels[0]),"budget crossed numeric dispatch boundary");if(budget<7)require(equal(h.voice.State(),initial),"budget changed voice state");}});
    suite.test("VM Busy and retained raw vector lifetime on channel one",[]{Host h;nnn::CExecScript vm(h);h.vm=&vm;h.apply=false;auto w=decoded("voice1_labels.spt");h.during=[&](Word ch){require(ch==1&&vm.GetPC()==32,"callback channel/PC");status(vm.Exec().status,ErrorCode::Busy);status(vm.LoadBytes(encoded(w),"nested"),ErrorCode::Busy);};load(vm,w);status(vm.Exec().status,ErrorCode::Ok);load(vm,decoded("voice01_labels.spt"));require(h.retained==std::vector<std::vector<Value>>{{1,-999}},"retained arguments borrowed source");});
    for(const auto& c:dw017_fixture::cases())for(const auto p:{ScriptControlProfile::Closed,ScriptControlProfile::Foreground})suite.test("fixed source channel trace "+c.name+(p==ScriptControlProfile::Closed?" Closed":" Foreground"),[&,p]{Host h;nnn::CExecScript vm(h);h.vm=&vm;h.apply=false;status(vm.LoadBytes(fixture(c.filename),c.name,{},nullptr,p),ErrorCode::Ok);for(const auto& step:c.steps){const auto r=vm.Exec();status(r.status,ErrorCode::Ok);require(r.return_code==step.return_code&&r.pc==step.pc&&vm.GetCallDepth()==step.frames.size(),"fixed PC/return/frame mismatch");}require(json_array(h.events)==c.callback_json&&h.pcs.size()==c.callback_states.size()&&h.reads==0,"fixed callback sequence or evaluated raw number");for(std::size_t i=0;i<h.pcs.size();++i)require(h.pcs[i]==c.callback_states[i].pc&&c.callback_states[i].frames.empty(),"fixed current callback PC");});
    for(const bool labels:{false,true})for(const auto p:{ScriptControlProfile::Closed,ScriptControlProfile::Foreground}){
        const std::string name=std::string(labels?" labels":" legacy")+(p==ScriptControlProfile::Closed?" Closed":" Foreground");const auto file=labels?"voice1_labels.spt":"voice1_legacy7.spt";
        suite.test("other channel numbers dispatch unchanged"+name,[=]{for(const Word ch:{2U,3U,UINT32_MAX}){auto w=decoded(file);w[36]=ch;format_expect_numeric(encoded(w),p,0x66660007U,volume,{ch,0xfffffc19U});}});
        suite.test("other delta bits and minus101 remain closed"+name,[=]{for(const Word delta:{0U,UINT32_MAX,0xffffff9bU,0x80000007U,0x90000007U}){auto w=decoded(file);w[37]=delta;format_expect_numeric(encoded(w),p,0x66660007U,volume,{1,delta});}});
        suite.test("count mismatch remains invalid"+name,[=]{for(const Word count:{0U,1U,3U,UINT32_MAX}){auto w=decoded(file);w[35]=count;reject(w,ErrorCode::InvalidFormat,p);}});
        suite.test("VOICE and adjacent channel opcodes use structural rules"+name,[=]{for(const Word code:{0x33330008U,0x33330067U,0x33330068U}){auto w=decoded(file);w[34]=code;if(code==0x33330008U)reject(w,ErrorCode::InvalidFormat,p);else format_expect_numeric(encoded(w),p,0x66660007U,code,{1,0xfffffc19U});}});
    }
    suite.test("failed channel load preserves loaded PC and both voice states",[]{Host h;nnn::CExecScript vm(h);h.vm=&vm;status(h.voice.SetState(seed()),ErrorCode::Ok);auto w=decoded("voice1_labels.spt");load(vm,w,ScriptControlProfile::Foreground);status(vm.Exec().status,ErrorCode::Ok);const auto before=h.voice.State();w[35]=3;status(vm.LoadBytes(encoded(w),"bad"),ErrorCode::InvalidFormat);require(vm.GetPC()==44&&vm.Identity()=="channel"&&vm.HasForegroundControls()&&equal(h.voice.State(),before),"failed load replaced live state");});
    std::cout<<"VOICE CHANNEL RESULT "<<suite.passed<<" passed, "<<suite.failed<<" failed\n";return suite.failed==0?0:1;
}
